// Minimal stdio MCP client: spawns the exact server command registered in OpenClaw.
// usage: node mcp-call.mjs '<json array of [toolName, args]>'
import { spawn } from 'node:child_process';
const calls = JSON.parse(process.argv[2]);
const p = spawn('/harness-state/.bun/bin/gbrain', ['serve', '--surface', 'starter', '--advertise', 'verbs'], {
  env: { ...process.env, GBRAIN_HOME: '/harness-state' }, stdio: ['pipe', 'pipe', 'pipe'], cwd: '/workspace',
});
let buf = ''; const pending = new Map(); let id = 0;
p.stdout.on('data', (d) => {
  buf += d; let i;
  while ((i = buf.indexOf('\n')) >= 0) {
    const line = buf.slice(0, i); buf = buf.slice(i + 1);
    if (!line.trim()) continue;
    let m; try { m = JSON.parse(line); } catch { continue; }
    if (m.id !== undefined && pending.has(m.id)) { pending.get(m.id)(m); pending.delete(m.id); }
  }
});
let err = ''; p.stderr.on('data', (d) => { err += d; });
const rpc = (method, params) => new Promise((res) => { const n = ++id; pending.set(n, res); p.stdin.write(JSON.stringify({ jsonrpc: '2.0', id: n, method, params }) + '\n'); });
const t = setTimeout(() => { console.error('TIMEOUT\n' + err.slice(-2000)); process.exit(1); }, 90000);
const init = await rpc('initialize', { protocolVersion: '2025-06-18', capabilities: {}, clientInfo: { name: 'install-check', version: '1' } });
console.log('server:', JSON.stringify(init.result?.serverInfo ?? init.error));
p.stdin.write(JSON.stringify({ jsonrpc: '2.0', method: 'notifications/initialized' }) + '\n');
const tl = await rpc('tools/list', {});
console.log('tools:', (tl.result?.tools ?? []).map((x) => x.name).join(', '));
for (const [name, args] of calls) {
  const r = await rpc('tools/call', { name, arguments: args });
  const text = r.error ? JSON.stringify(r.error) : (r.result?.content ?? []).map((c) => c.text ?? '').join('\n');
  console.log(`\n== ${name} ${JSON.stringify(args)}\nisError=${!!r.result?.isError}\n${text.slice(0, 1800)}`);
}
clearTimeout(t); p.stdin.end(); p.kill(); process.exit(0);

